fn reverse(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut a_rev = Vec::with_capacity(n); // Preallocate memory for the output vector

    for i in (0..n).rev() { // Iterate from the end to the beginning
        a_rev.push(a[i]); // Push the elements in reverse order
    }

    a_rev // Return the reversed vector
}